import { useState } from "react";
import { CurrencyInput } from "@nativecn/ui/premium/inputs/currency-input";

export default function App() {
  const [amount, setAmount] = useState(0);
  return (
    <CurrencyInput
      value={amount}
      onChangeValue={setAmount}
      currency="USD"
      label="Amount"
    />
  );
}
